templates.code:
apiVersion: monitoring.coreos.com/v1
kind: ServiceMonitor
metadata:
  name: {nombre}
  namespace: {ns_app}
  labels:
    release: {release}
spec:
  selector:
    matchLabels:
      app.kubernetes.io/name: {app}
  endpoints:
    - port: {puerto}
      path: /metrics
      interval: {intervalo}

apiVersion: monitoring.coreos.com/v1
kind: PodMonitor
metadata:
  name: {nombre}
  namespace: {ns_app}
  labels:
    release: {release}
spec:
  selector:
    matchLabels:
      app.kubernetes.io/name: {app}
  podMetricsEndpoints:
    - port: {puerto_pod}
      interval: {intervalo}

apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: {nombre}
  namespace: {ns_app}
  labels:
    release: {release}
spec:
  groups:
    - name: {grupo}
      rules:
        - alert: {Alerta}
          expr: {expr}
          for: {for}
          labels:
            severity: {severidad}

curl -s 'http://{prometheus}/api/v1/rules?type=alert' \
  | jq -r '.data.groups[].rules[] | [.name, .state, .health, .lastError] | @tsv'
amtool --alertmanager.url=http://{alertmanager} alert query alertname={alerta}
